#!/usr/bin/env python3
"""Suzunari music (all original, generated by code): three seamless loops for the town, replacing the inherited
ODD-SPACE synthwave (docs/REVIEW.md hard review #5).
  suzunari_morning    - yo scale on D, koto plucks, wind chimes, soft pad (morning -> afternoon)
  suzunari_dusk       - miyako-bushi on E, breathy shakuhachi, low koto ostinato, temple bell (Omagatoki)
  suzunari_rain_night - A minor pentatonic lullaby on a soft piano, pad, rain bed (night, or when Amane cries)
Writes assets/audio/music/<name>.ogg (ffmpeg + libvorbis). python3 tools/gen_music_suzunari.py"""
import os, subprocess, tempfile, wave
import numpy as np

SR = 32000
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
OUT = os.path.join(ROOT, "assets", "audio", "music")


def mtof(m):
    return 440.0 * 2 ** ((m - 69) / 12.0)


def env(n, a, r_tau):
    t = np.arange(n) / SR
    e = np.exp(-t / r_tau)
    na = max(1, int(a * SR))
    e[:na] *= np.linspace(0, 1, na)
    return e


def koto(f, dur, vel=1.0, rng=None):
    n = int(dur * SR)
    t = np.arange(n) / SR
    out = np.zeros(n)
    for k in range(1, 9):
        fk = f * k * (1 + 0.0008 * k * k)
        if fk > SR / 2.2:
            break
        amp = (1.0 / k) * (0.9 if k % 2 else 0.6)
        out += amp * np.sin(2 * np.pi * fk * t) * np.exp(-t * (1.6 + 0.9 * k))
    click = (rng.standard_normal(n) if rng is not None else np.zeros(n)) * np.exp(-t * 180) * 0.15
    e = env(n, 0.003, 10.0)
    return (out + click) * e * vel * 0.35


def shakuhachi(f, dur, vel=1.0, rng=None):
    n = int(dur * SR)
    t = np.arange(n) / SR
    vib = 1 + 0.006 * np.sin(2 * np.pi * 5.0 * t) * np.clip(t / 0.8, 0, 1)
    ph = 2 * np.pi * np.cumsum(f * vib) / SR
    tone = np.sin(ph) + 0.25 * np.sin(2 * ph) + 0.08 * np.sin(3 * ph)
    noise = rng.standard_normal(n)
    # crude breath: smoothed noise riding on the tone
    k = 24
    noise = np.convolve(noise, np.ones(k) / k, mode="same")
    a = np.clip(t / 0.25, 0, 1) * np.clip((dur - t) / 0.35, 0, 1)
    swell = 0.8 + 0.2 * np.sin(np.pi * np.clip(t / max(dur, 0.01), 0, 1))
    return (tone * 0.36 + noise * 0.5) * a * swell * vel * 0.4


def bell(f, dur, vel=1.0):
    n = int(dur * SR)
    t = np.arange(n) / SR
    out = np.zeros(n)
    for ratio, amp, tau in [(1.0, 1.0, 3.5), (2.76, 0.5, 2.2), (5.4, 0.25, 1.2), (8.93, 0.12, 0.6), (0.5, 0.3, 4.5)]:
        out += amp * np.sin(2 * np.pi * f * ratio * t + 0.3 * np.sin(2 * np.pi * 1.3 * t)) * np.exp(-t / tau)
    return out * env(n, 0.002, 99) * vel * 0.18


def chime(f, dur, vel=1.0):
    n = int(dur * SR)
    t = np.arange(n) / SR
    out = np.sin(2 * np.pi * f * t) + 0.4 * np.sin(2 * np.pi * f * 2.71 * t) * np.exp(-t * 3)
    return out * np.exp(-t / 1.4) * env(n, 0.001, 99) * vel * 0.1


def piano(f, dur, vel=1.0):
    n = int(dur * SR)
    t = np.arange(n) / SR
    out = np.zeros(n)
    for k in range(1, 7):
        fk = f * k * (1 + 0.0004 * k * k)
        out += (1.0 / (k ** 1.3)) * np.sin(2 * np.pi * fk * t) * np.exp(-t * (0.9 + 0.7 * k))
    rel = np.clip((dur - t) / 0.4, 0, 1)
    return out * env(n, 0.004, 99) * rel * vel * 0.3


def pad(freqs, dur, vel=1.0):
    n = int(dur * SR)
    t = np.arange(n) / SR
    out = np.zeros(n)
    for f in freqs:
        for det in (-0.003, 0.003):
            out += np.sin(2 * np.pi * f * (1 + det) * t) + 0.2 * np.sin(4 * np.pi * f * t)
    a = np.clip(t / (dur * 0.35), 0, 1) * np.clip((dur - t) / (dur * 0.35), 0, 1)
    return out * a * vel * 0.05 / max(1, len(freqs))


def add(buf, sig, at):
    i = int(at * SR) % len(buf)
    n = len(sig)
    end = i + n
    if end <= len(buf):
        buf[i:end] += sig
    else:  # wrap around: the loop is seamless
        k = len(buf) - i
        buf[i:] += sig[:k]
        rest = sig[k:]
        while len(rest) > 0:
            m = min(len(rest), len(buf))
            buf[:m] += rest[:m]
            rest = rest[m:]


def reverb(buf, seconds=2.6, wet=0.32, seed=1):
    rng = np.random.default_rng(seed)
    n = len(buf)
    m = int(seconds * SR)
    ir = rng.standard_normal(m) * np.exp(-np.arange(m) / SR * (6.9 / seconds))
    ir = np.convolve(ir, np.ones(8) / 8, mode="same")  # darker
    ir /= np.sqrt(np.sum(ir ** 2))
    pad_ir = np.zeros(n)
    pad_ir[:m] = ir
    wet_sig = np.real(np.fft.ifft(np.fft.fft(buf) * np.fft.fft(pad_ir)))  # circular = seamless loop
    return buf * (1 - wet * 0.5) + wet_sig * wet


def lowpass(x, a=0.08):
    y = np.zeros_like(x)
    acc = 0.0
    for i in range(len(x)):
        acc += a * (x[i] - acc)
        y[i] = acc
    return y


def melody(rng, scale, bars, beats_per_bar, start_idx, rhythms, rest_p=0.12):
    """Stepwise melody over a scale index line; returns [(beat, length_beats, scale_index)]. Ends on the tonic."""
    notes = []
    idx = start_idx
    beat = 0.0
    for bar in range(bars):
        pattern = rhythms[rng.integers(len(rhythms))]
        for j, ln in enumerate(pattern):
            last = bar == bars - 1 and j == len(pattern) - 1
            if last:
                idx = start_idx
            elif rng.random() > rest_p or j == 0:
                step = rng.choice([-2, -1, -1, 0, 1, 1, 2], p=[0.08, 0.25, 0.1, 0.1, 0.25, 0.1, 0.12])
                idx = int(np.clip(idx + step, 0, len(scale) - 1))
            else:
                beat += ln
                continue
            notes.append((beat, ln, idx))
            beat += ln
    return notes


def write_ogg(name, buf):
    buf = buf / (np.max(np.abs(buf)) + 1e-9) * 0.82
    pcm = (buf * 32767).astype(np.int16)
    with tempfile.TemporaryDirectory() as tmp:
        wav_path = os.path.join(tmp, name + ".wav")
        with wave.open(wav_path, "wb") as w:
            w.setnchannels(1)
            w.setsampwidth(2)
            w.setframerate(SR)
            w.writeframes(pcm.tobytes())
        out = os.path.join(OUT, name + ".ogg")
        subprocess.run(["ffmpeg", "-y", "-loglevel", "error", "-i", wav_path, "-c:a", "libvorbis", "-q:a", "4", out], check=True)
    print("wrote", os.path.relpath(out, ROOT), "%.1f s" % (len(buf) / SR))


def morning():
    rng = np.random.default_rng(408)
    bpm, bars, bpb = 84, 16, 4
    spb = 60.0 / bpm
    buf = np.zeros(int(bars * bpb * spb * SR))
    yo = [62, 64, 67, 69, 71, 74, 76, 79, 81]  # D yo scale
    mel = melody(rng, yo, bars, bpb, 2, [[1, 1, 2], [0.5, 0.5, 1, 2], [2, 1, 1], [1, 0.5, 0.5, 2], [1, 1, 1, 1]])
    for beat, ln, i in mel:
        add(buf, koto(mtof(yo[i]), max(1.2, ln * spb + 0.8), 0.9, rng), beat * spb)
        if rng.random() < 0.25:  # koto grace: the note a fourth below, a beat later
            add(buf, koto(mtof(yo[max(0, i - 2)]), 1.0, 0.45, rng), (beat + ln * 0.5) * spb)
    roots = [50, 50, 55, 50, 57, 55, 50, 50]
    for bar in range(bars):
        r = roots[bar % len(roots)]
        add(buf, koto(mtof(r - 12), 2.4, 0.7, rng), bar * bpb * spb)
        add(buf, koto(mtof(r - 5), 1.6, 0.4, rng), (bar * bpb + 2) * spb)
        add(buf, pad([mtof(r), mtof(r + 7), mtof(r + 14)], bpb * spb * 1.2, 0.8), bar * bpb * spb)
    for _ in range(26):  # furin wind chimes, now and then
        add(buf, chime(mtof(int(rng.choice([86, 88, 91, 93, 95]))), 2.5, rng.uniform(0.4, 0.9)), rng.uniform(0, len(buf) / SR))
    write_ogg("suzunari_morning", reverb(buf, 2.2, 0.3, 3))


def dusk():
    rng = np.random.default_rng(1800)
    bpm, bars, bpb = 64, 12, 4
    spb = 60.0 / bpm
    buf = np.zeros(int(bars * bpb * spb * SR))
    miyako = [64, 65, 69, 71, 72, 76, 77, 81]  # E miyako-bushi
    mel = melody(rng, miyako, bars, bpb, 3, [[4], [2, 2], [3, 1], [1, 3], [2, 1, 1]], rest_p=0.3)
    for beat, ln, i in mel:
        add(buf, shakuhachi(mtof(miyako[i]), ln * spb * 0.95, 0.85, rng), beat * spb)
    for b in range(bars * bpb):
        pat = [52, 59, 64, 59]
        add(buf, koto(mtof(pat[b % 4] - 12), 1.6, 0.5 if b % 4 else 0.75, rng), b * spb)
    for bar in range(0, bars, 4):
        add(buf, bell(mtof(40), 7.0, 1.0), bar * bpb * spb + 0.1)
    for bar in range(bars):
        add(buf, pad([mtof(52), mtof(59), mtof(64 if bar % 2 else 65)], bpb * spb * 1.3, 0.9), bar * bpb * spb)
    write_ogg("suzunari_dusk", reverb(buf, 3.4, 0.42, 5))


def rain_night():
    rng = np.random.default_rng(2125)
    bpm, bars, bpb = 60, 12, 3  # a lullaby in 3
    spb = 60.0 / bpm
    buf = np.zeros(int(bars * bpb * spb * SR))
    pent = [57, 60, 62, 64, 67, 69, 72, 74, 76]  # A minor pentatonic
    mel = melody(rng, pent, bars, bpb, 5, [[2, 1], [1, 1, 1], [3], [1, 2]], rest_p=0.15)
    for beat, ln, i in mel:
        add(buf, piano(mtof(pent[i]), ln * spb + 0.9, 0.8), beat * spb)
    chords = [[45, 52, 60], [41, 48, 57], [43, 50, 59], [45, 52, 57]]
    for bar in range(bars):
        c = chords[bar % len(chords)]
        add(buf, piano(mtof(c[0]), bpb * spb, 0.55), bar * bpb * spb)
        for k, m in enumerate(c[1:]):
            add(buf, piano(mtof(m), spb * 1.8, 0.3), (bar * bpb + 1 + k) * spb)
        add(buf, pad([mtof(m + 12) for m in c], bpb * spb * 1.4, 0.7), bar * bpb * spb)
    rain = lowpass(rng.standard_normal(len(buf)), 0.12) * 0.05
    drops = np.zeros(len(buf))
    for _ in range(int(len(buf) / SR * 18)):
        i = rng.integers(len(buf) - 400)
        drops[i:i + 400] += rng.standard_normal(400) * np.exp(-np.arange(400) / 40.0) * rng.uniform(0.02, 0.07)
    for _ in range(10):
        add(buf, chime(mtof(int(rng.choice([88, 91, 93]))), 2.5, 0.4), rng.uniform(0, len(buf) / SR))
    write_ogg("suzunari_rain_night", reverb(buf, 3.0, 0.38, 7) + rain + drops * 0.6)


if __name__ == "__main__":
    os.makedirs(OUT, exist_ok=True)
    morning()
    dusk()
    rain_night()
